<?php include __DIR__.'/../partials/header.php'; ?><section class="page-head"><div><p class="eyebrow">TRANSAKSI</p><h1>Parkir keluar</h1><p class="muted">Cari kendaraan berdasarkan plat nomor untuk menghitung tagihan.</p></div></section><form class="search" method="get"><input type="hidden" name="page" value="keluar"><input name="plat" value="<?=htmlspecialchars($plat)?>" placeholder="Cari plat nomor..."><button class="button">Cari kendaraan</button></form><?php if($plat&& !$hasil):?><div class="alert error">Kendaraan tidak ditemukan atau sudah keluar.</div><?php endif;?><?php foreach($hasil as $p):$jam=max(1,(int)ceil((time()-strtotime($p['waktu_masuk']))/3600));$total=$p['jenis_roda']==='2'?2000+max(0,$jam-1)*1000:5000+max(0,$jam-1)*1000;?><article class="result"><div><p class="eyebrow">KENDARAAN DITEMUKAN</p><h2><?=htmlspecialchars($p['plat_nomor'])?></h2><p class="muted">Roda <?=$p['jenis_roda']?> · Masuk <?=$p['waktu_masuk']?> · Durasi <?=$jam?> jam</p></div><div class="price">Rp <?=number_format($total,0,',','.')?></div><button class="button" onclick="openPay(<?=$p['id']?>, '<?=htmlspecialchars($p['plat_nomor'],ENT_QUOTES)?>', '<?=number_format($total,0,',','.')?>')">Proses keluar</button></article><?php endforeach;?><dialog id="pay"><form method="post" action="index.php?page=proses-keluar"><h2>Konfirmasi pembayaran</h2><p id="pay-text"></p><input type="hidden" name="id" id="pay-id"><button class="button">Simpan transaksi & kendaraan keluar</button><button type="button" class="button secondary" onclick="pay.close()">Batal</button></form></dialog><script>function openPay(id,plat,total){document.getElementById('pay-id').value=id;document.getElementById('pay-text').textContent='Total yang harus dibayar untuk '+plat+' adalah Rp '+total+'.';pay.showModal()}</script><?php include __DIR__.'/../partials/footer.php';?>
